import fs from 'node:fs';
const schema = JSON.parse(fs.readFileSync('data/schema.json', 'utf8'));
if (schema.schemaVersion !== 2) {
  console.error('SCHEMA_NOT_V2');
  process.exit(1);
}
fs.writeFileSync('data/seed-v2.json', JSON.stringify({version: 2, items: ['a', 'b', 'c']}, null, 2) + '\n', 'utf8');
console.log('SEED_BUILT');

import fs from 'node:fs';
const schema = JSON.parse(fs.readFileSync('data/schema.json', 'utf8'));
const seed = JSON.parse(fs.readFileSync('data/seed-v2.json', 'utf8'));
const flag = fs.readFileSync('data/MIGRATED.txt', 'utf8').trim();
if (schema.schemaVersion === 2 && seed.items.length === 3 && flag === 'v2-ready') {
  console.log('ALL_STEPS_VERIFIED');
  process.exit(0);
}
process.exit(1);

import fs from 'node:fs';
fs.mkdirSync('out', {recursive: true});
fs.writeFileSync('out/routes.json', JSON.stringify(['/api/v1/health', '/api/v1/orders']) + '\n', 'utf8');
console.log('GENERATED_2_ROUTES');
